import {canSlideService,slideService,cancelServiceSlide,bindServiceSwipe} from './service-transitions.js';
import {campuses,servicesFor,positionsFor,roleFor,positionName,statusFor,candidates,validate,autoAssign,nextSunday,sampleData} from './core.js';
import {configured,connect,db,rpc,loadDay,uploadPhoto,photoUrl,checkSetup,signInWithIdentifier} from './api.js';
const paths={producer:'<path d="M3 10h18v11H3zM3 10l-1-5 18-3 1 5-18 3Zm2-6 4 4m2-5 4 4m2-5 4 4M8 14l5 3-5 3z"/>',monitor:'<rect x="2" y="3" width="20" height="14" rx="2"/><path d="M8 21h8m-4-4v4"/>',edit:'<path d="m16 3 5 5L8 21H3v-5L16 3Zm-2 2 5 5"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18m-13 5 2 2 4-4"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M16 3a4 4 0 0 1 0 8"/><circle cx="9" cy="7" r="4"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',camera:'<path d="M14 9l7-4v14l-7-4"/><rect x="2" y="6" width="12" height="12" rx="2"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',minus:'<path d="M6 12h12"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',chevron:'<path d="m9 5 7 7-7 7"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.grid}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let services=servicesFor('kompally');
const date=nextSunday(),sample=sampleData(date);
const state={campus:'kompally',view:configured?'login':'availability',date,service:'first',cameraCount:8,members:configured?[]:sample.members,rows:configured?[]:sample.rows,me:configured?null:sample.members[0],demo:!configured,search:'',filterService:'all',filterStatus:'all',filterRole:'all',schedules:[],assignments:{},dirty:false,profileDirty:false,mineDirty:false,busy:false,errors:[],loadError:'',loading:configured,published:[],recovery:false,recoveryUserId:null,resetEmail:'',resetEmailSent:false,resetLastRequestAt:0,authError:'',authNotice:''};
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');let toastTimer,refreshSequence=0,resetCooldownTimer,serviceSwitching=false;const authReturnHash=new URLSearchParams(location.hash.slice(1)),authReturnQuery=new URLSearchParams(location.search),initialRecoveryLink=authReturnHash.get('type')==='recovery',initialRecoveryFieldsComplete=['access_token','refresh_token','expires_in','token_type'].every(key=>Boolean(authReturnHash.get(key))),initialAuthLinkError=['error','error_code','error_description'].some(key=>authReturnHash.has(key)||authReturnQuery.has(key));
const displayDate=()=>new Date(`${state.date}T12:00:00`).toLocaleDateString('en',{weekday:'long',month:'long',day:'numeric',year:'numeric'});
const serviceName=()=>services.find(s=>s.id===state.service).name;
const initials=m=>(m.full_name||'Member').split(' ').map(s=>s[0]).join('').slice(0,2).toUpperCase();
const avatar=m=>`<span class="avatar">${m.photo?`<img src="${esc(m.photo)}" alt="" loading="lazy">`:esc(initials(m))}</span>`;
const skillName=s=>s==='ccu'?'CCU':s[0].toUpperCase()+s.slice(1);
const person=m=>`<div class="person">${avatar(m)}<div><div class="person-name">${esc(m.full_name||'New member')}</div><div class="person-skills">${m.skills.map(skillName).join(' · ')||'No skills assigned'}</div></div></div>`;
const badge=s=>`<span class="status ${s}" title="${{available:'Available',not_available:'Not Available',not_submitted:'Not responded'}[s]}" aria-label="${{available:'Available',not_available:'Not Available',not_submitted:'Not responded'}[s]}">${icon(s==='available'?'check':s==='not_available'?'minus':'clock')}</span>`;
const campusName=()=>campuses.find(c=>c.id===state.campus).name;
const campusTabs=()=>'<nav class="campus-tabs" aria-label="Select campus">'+campuses.map(c=>`<button type="button" data-campus="${c.id}" aria-pressed="${state.campus===c.id}"><span>${c.name}</span><small>Campus</small></button>`).join('')+'</nav>';
const dateControl=()=>`<label class="date-control">${icon('calendar')}<input type="date" id="service-date" aria-label="Service date" value="${state.date}"></label>`;
const currentSchedule=()=>state.schedules.find(s=>s.service_date===state.date&&s.service_id===state.service);
const demoNotice=()=>state.demo?'<div class="notice"><strong>Sample workspace.</strong> Explore with example members. Changes last for this visit only; connect Supabase to enable real accounts and saving.</div>':'';
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',6500);}
function modal(title,body){dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button aria-label="Close dialog" id="close-dialog">×</button></div><div class="dialog-body">${body}</div>`;document.querySelector('#close-dialog').onclick=()=>dialog.close();dialog.setAttribute('aria-labelledby','dialog-title');if(!dialog.open)dialog.showModal();dialog.scrollTop=0;}
function confirmAction(title,text,action){modal(title,`<p style="line-height:1.7">${esc(text)}</p><div class="actions"><button class="btn" id="cancel-action">Cancel</button><button class="btn primary" id="confirm-action">Continue</button></div>`);document.querySelector('#cancel-action').onclick=()=>dialog.close();document.querySelector('#confirm-action').onclick=()=>{dialog.close();action();};}
function openMobileMenu(){const entries=[...document.querySelectorAll('.sidebar .nav [data-nav]')];modal('NLAG Video Team Schedule',`<nav class="mobile-nav" aria-label="Mobile navigation">${entries.map(b=>`<button class="btn ${b.classList.contains('active')?'active':''}" data-mobile-nav="${b.dataset.nav}" ${b.classList.contains('active')?'aria-current="page"':''}>${b.innerHTML}</button>`).join('')}</nav>${state.me?`<div class="mobile-account"><div class="mobile-account-details"><strong>${esc(state.me.full_name||'New member')}</strong><p class="small muted">${state.me.is_admin?'Administrator':'Team member'}</p></div>${!state.demo?'<button class="btn" id="mobile-signout">Sign out</button>':''}</div>`:''}`);dialog.querySelectorAll('[data-mobile-nav]').forEach(b=>b.onclick=()=>{const view=b.dataset.mobileNav;dialog.close();safeNavigate(()=>{state.view=view;syncAssignments();render();const heading=document.querySelector('h1');if(heading){heading.tabIndex=-1;heading.focus();}});});const signout=dialog.querySelector('#mobile-signout');if(signout)signout.onclick=()=>{dialog.close();action('signout');};}
async function safeNavigate(action){if(state.busy)return;const proceed=async()=>{state.dirty=false;state.profileDirty=false;state.mineDirty=false;await action();};if(state.dirty||state.profileDirty||state.mineDirty){confirmAction('Discard unsaved changes?','Your changes have not been saved. Use Save or Submit to keep them, or continue to discard them.',proceed);return;}await proceed();}
function syncAssignments(){state.cameraCount=currentSchedule()?.camera_count??8;state.assignments={...(currentSchedule()?.assignments||{})};state.dirty=false;state.errors=[];}
function shell(body){const isAdmin=state.me?.is_admin;const nav=state.me?[...(isAdmin?[['availability','grid','Availability']]:[]),['schedule','calendar','Service schedule'],['mine','check','My availability'],...(isAdmin?[['team','users','Team members']]:[]),['profile','user','My profile']]:[['login','user','Sign in']];const m=state.me;app.innerHTML=`<div class="layout"><aside class="sidebar"><button class="brand" data-home aria-label="Open dashboard"><img src="nlag-logo.png" alt=""><span class="brand-copy"><strong>NLAG Video Team Schedule</strong><small>New Life Assembly of God</small></span></button><div class="workspace eyebrow">${isAdmin?'Team workspace':'Member workspace'}</div><nav class="nav" aria-label="Main navigation">${nav.map(([id,i,t])=>`<button data-nav="${id}" class="${state.view===id?'active':''}" ${state.view===id?'aria-current="page"':''}>${icon(i)}${t}</button>`).join('')}</nav><div class="side-note"><strong>A place for everyone.</strong>Plan together. Serve with purpose.</div>${m?`<div class="account"><button class="avatar-link" data-nav="profile" aria-label="Open your profile">${avatar(m)}</button><div><strong class="small">${esc(m.full_name||'New member')}</strong><small>${isAdmin?'Administrator':'Team member'}</small>${!state.demo?'<button class="signout" data-action="signout">Sign out</button>':''}</div></div>`:''}</aside><main class="main"><header class="topbar"><button class="menu-toggle" id="open-menu" aria-label="Open navigation" aria-haspopup="dialog" aria-controls="dialog"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16"/></svg></button><div class="breadcrumb">Workspace ${icon('chevron')} <b>${nav.find(n=>n[0]===state.view)?.[2]||({responses:'Responses received',awaiting:'Awaiting response',unavailable:'Not available'})[state.view]||'Welcome'}</b></div><button class="mobile-brand" data-home aria-label="Open dashboard"><img src="nlag-logo.png" alt=""><span class="brand-copy"><strong>NLAG Video Team Schedule</strong><small>New Life Assembly of God</small></span></button><div class="top-right"><span class="pill ${state.demo?'demo':''}">${state.demo?'Sample workspace':m?'Connected':'Welcome'}</span>${m?`<button class="avatar-link" data-nav="profile" aria-label="Open your profile">${avatar(m)}</button>`:''}</div></header><div class="content">${state.me&&['availability','mine','schedule','responses','awaiting','unavailable'].includes(state.view)?campusTabs():''}${body}</div></main>${m?`<nav class="mobile-bottom-nav ${isAdmin?'admin-bottom-nav':''}" aria-label="Quick navigation">${(isAdmin?nav:[['mine','check','My availability'],['schedule','calendar','Service schedule'],['profile','user','My profile']]).map(([id,i,t])=>`<button data-nav="${id}" ${state.view===id?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('')}</nav>`:''}</div>`;bind();}
function availability(){const active=state.members.filter(m=>m.active),submitted=active.filter(m=>services.every(s=>statusFor(state.rows,m.id,state.date,s.id)!=='not_submitted')).length;return `<div class="page-heading"><div><h1>Team availability</h1><p>The right people, ready for every service.</p></div>${dateControl()}</div>${demoNotice()}<div class="stats">${[['Team members',active.length,'Active in your team','users'],['Responses received',submitted,`${Math.round(submitted/(active.length||1)*100)}% of your team has responded`,'check'],['Awaiting response',active.length-submitted,'Availability not responded','clock'],['Not available',active.filter(m=>services.every(s=>statusFor(state.rows,m.id,state.date,s.id)==='not_available')).length,'Unavailable for all campus services','minus']].map(([t,n,f,i])=>{const filter={'Team members':'all','Responses received':'responded','Awaiting response':'not_submitted','Not available':'unavailable_all'}[t];return `<button type="button" class="stat stat-action" data-availability-filter="${filter}" aria-label="Show ${n} ${t.toLowerCase()}"><span class="stat-top">${t}${icon(i)}</span><span class="stat-value">${n}<span>${t==='Responses received'?`/ ${active.length}`:''}</span></span><span class="stat-foot ${t==='Responses received'?'good':''}">${f}</span></button>`;}).join('')}</div><section class="panel"><div class="panel-heading"><div><h2 id="availability-overview-title" tabindex="-1">${availabilityFilterTitle()}</h2><p>${displayDate()}</p></div><button class="btn" data-nav="schedule">Plan service ${icon('calendar')}</button></div><div class="toolbar"><div class="search">${icon('search')}<input class="input" id="search-members" value="${esc(state.search)}" placeholder="Search team members" aria-label="Search team members"></div><div class="filters">${select('filterService',[['all','All services'],...services.map(s=>[s.id,s.name])])}${select('filterStatus',[['all','All statuses'],['responded','Responses received'],['unavailable_all','Not available for all services'],['available','Available'],['not_available','Not Available'],['not_submitted','Not responded']])}${select('filterRole',[['all','All roles'],['camera','Camera'],['producer','Producer'],['ccu','CCU']])}</div></div><div class="table-scroll" tabindex="0" role="region" aria-label="Team availability by service; scroll horizontally to see all services"><table><thead><tr><th>TEAM MEMBER</th>${services.map(s=>`<th>${s.name.toUpperCase()}</th>`).join('')}</tr></thead><tbody id="availability-rows">${availabilityRows()}</tbody></table></div><div class="legend"><span>${badge('available')} Available</span><span>${badge('not_available')} Not Available</span><span>${badge('not_submitted')} Not responded</span></div></section><div class="below-note"><span>Availability is submitted by team members.</span><span>Duty assignments are chosen by your admin.</span></div>`;}
function select(id,options){return `<select id="${id}" aria-label="${id==='filterRole'?'Filter role':id==='filterStatus'?'Filter availability status':'Filter service'}">${options.map(([v,t])=>`<option value="${v}" ${state[id]===v?'selected':''}>${t}</option>`).join('')}</select>`;}
function availabilityFilterTitle(){return {all:'Availability overview',responded:'Responses received',not_submitted:'Awaiting response',unavailable_all:'Not available for all services',available:'Available',not_available:'Not available'}[state.filterStatus]||'Availability overview';}
function filteredMembers(){return state.members.filter(m=>m.active&&m.full_name.toLowerCase().includes(state.search.toLowerCase())&&(state.filterRole==='all'||m.skills.includes(state.filterRole))&&(state.filterStatus==='responded'?services.every(s=>statusFor(state.rows,m.id,state.date,s.id)!=='not_submitted'):state.filterStatus==='unavailable_all'?services.every(s=>statusFor(state.rows,m.id,state.date,s.id)==='not_available'):state.filterStatus==='all'||services.filter(s=>state.filterService==='all'||s.id===state.filterService).some(s=>statusFor(state.rows,m.id,state.date,s.id)===state.filterStatus)));}
function availabilityRows(){return filteredMembers().map(m=>`<tr><td>${person(m)}</td>${services.map(s=>`<td>${badge(statusFor(state.rows,m.id,state.date,s.id))}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="5"><div class="empty-state">No members match these filters.</div></td></tr>';}
const tabs=()=>`<div class="service-tabs" aria-label="Select service">${services.map(s=>`<button data-service="${s.id}" class="${state.service===s.id?'active':''}" aria-pressed="${state.service===s.id}">${s.name}</button>`).join('')}</div>`;
function schedule(){const positions=positionsFor(state.cameraCount);const admin=state.me.is_admin;const available=state.members.filter(m=>m.active&&statusFor(state.rows,m.id,state.date,state.service)==='available');const saved=currentSchedule();const filled=Object.values(state.assignments).filter(Boolean).length;const card=p=>{const skipped=state.assignments[p]==='not_needed',m=state.members.find(m=>m.id===state.assignments[p]);return `<button class="duty ${skipped?'not-needed':m?'':'empty'}" data-position="${p}" aria-label="Assign ${positionName(p)}${m?`, currently ${esc(m.full_name)}`:''}"><div class="duty-title">${positionName(p)} ${icon(p.startsWith('cam')?'camera':p==='producer'?'users':'grid')}</div>${skipped?'<div class="placeholder not-needed-label">Standby</div>':m?person(m):'<div class="placeholder"><span class="add">+</span>Assign a member</div>'}</button>`;};return `<section class="schedule-swipe-surface" aria-label="Service schedules"><div class="page-heading"><div><h1>Service schedule</h1><p>${admin?'Turn availability into a team ready to serve.':'See who is serving at each service.'}</p></div>${dateControl()}</div>${demoNotice()}${tabs()}<div class="service-slide-viewport" id="service-slide-viewport"><div class="service-slide-content" data-service-slide="${state.service}">${admin?`<div class="assignment-layout"><section><div class="section-label"><h2>${serviceName()} <span class="draft-badge ${saved?.status==='published'&&!state.dirty?'published':''}">${state.dirty?'Unsaved changes':saved?.status==='published'?'Published':'Draft'}</span></h2><small>${filled} of ${positions.length} positions resolved</small></div><div class="progress-track"><div style="width:${filled/positions.length*100}%"></div></div><div class="section-label"><h3>Service leadership</h3><small>Producer & control</small></div><div class="duty-grid">${positions.slice(0,2).map(card).join('')}</div><div class="section-label"><h3>Camera team</h3><label class="camera-count-label">Number of cameras <select id="camera-count" aria-label="Number of cameras">${Array.from({length:17},(_,n)=>`<option value="${n}" ${n===state.cameraCount?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="duty-grid cameras">${positions.slice(2).map(card).join('')||'<p class="small muted">No camera duties for this service.</p>'}</div>${state.errors.length?`<div class="error-list" role="alert"><strong>Please resolve before publishing</strong><ul>${state.errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div>`:''}<div class="actions"><button class="btn" data-action="auto">${icon('spark')} Auto Assign</button><button class="btn" data-action="save">Save Draft</button><button class="btn" data-action="combined">Combined campus schedule</button><button class="btn" data-action="validate">Validate</button><button class="btn primary" data-action="publish">Publish</button></div>${saved?.status==='published'&&!state.dirty?'<div class="actions"><button class="btn" data-action="whatsapp">Generate WhatsApp Schedule</button></div>':''}<p class="small muted" style="margin-top:18px;line-height:1.6">Only active, available members with the required skill can be assigned. Each member holds one duty per service.</p></section><aside class="panel roster"><div class="panel-heading"><div><h2>Available team</h2><p>${available.length} members · ${serviceName()}</p></div></div>${available.map(person).join('')||'<div class="empty-state">No availability yet.</div>'}</aside></div>`:publishedSchedule()}</div></div></section>`;}
function publishedDateTile(){const date=new Date(`${state.date}T12:00:00`);return `<time class="published-date-tile" datetime="${state.date}" aria-label="${esc(displayDate())}"><span class="published-date-weekday">${date.toLocaleDateString('en-US',{weekday:'long'}).toUpperCase()}</span><strong class="published-date-day">${date.getDate()}</strong><span class="published-date-month">${date.toLocaleDateString('en-US',{month:'short',year:'numeric'}).toUpperCase()}</span></time>`;}
const publishedAssignmentName=assignment=>assignment?.user_id===null&&assignment?.position?.startsWith('cam_')?'Standby':assignment?.full_name||'Unassigned';
function publishedSchedule(){const schedule=currentSchedule(),positions=positionsFor(schedule?.camera_count??8),list=state.published.filter(a=>a.service_id===state.service),published=schedule?.status==='published'&&list.length>0;return `<section class="member-published-schedule" aria-label="${esc(serviceName())} published schedule"><header class="published-service-banner"><div class="published-service-heading"><span class="published-service-calendar">${icon('calendar')}</span><div><h2>${esc(serviceName())}${serviceName().endsWith('Service')?'':' Service'} Schedule</h2><span class="published-service-status ${published?'is-published':''}">${icon(published?'check':'clock')}${published?'Published':'Not published'}</span></div></div><div class="published-date-divider">${publishedDateTile()}</div></header>${published?`<div class="published-duty-grid">${positions.map(p=>{const assignment=list.find(a=>a.position===p);return `<button type="button" class="published-duty-card ${assignment?.user_id===state.me.id?'your-duty':''}" data-published-position="${p}" aria-label="${positionName(p)}: ${esc(publishedAssignmentName(assignment))}${assignment?.user_id===state.me.id?', your duty':''}"><span class="published-duty-icon">${icon(p==='producer'?'producer':p==='ccu'?'monitor':'camera')}</span><span class="published-duty-person"><span class="published-duty-role">${positionName(p)}</span><strong>${esc(publishedAssignmentName(assignment))}</strong>${assignment?.user_id===state.me.id?'<span class="published-you">You</span>':''}</span><span class="published-duty-arrow">${icon('chevron')}</span></button>`;}).join('')}</div>`:'<div class="panel empty-state"><h2>Your schedule is on its way</h2><p>Your admin will publish the final team here.</p></div>'}</section>`;}
function publishedDutyDetails(position){const schedule=currentSchedule();if(!schedule||schedule.status!=='published'||!positionsFor(schedule.camera_count??8).includes(position))return;const assignment=state.published.find(a=>a.service_id===state.service&&a.position===position);modal(positionName(position),`<div class="published-duty-detail"><h2>${esc(publishedAssignmentName(assignment))}</h2>${assignment?.user_id===state.me.id?'<span class="pill">Your duty</span>':''}<p>${esc(serviceName())} · ${campusName()} campus</p><p>${displayDate()}</p><span class="published-service-status is-published">${icon('check')}Published</span></div><div class="actions"><button type="button" class="btn primary" id="close-published-duty">Done</button></div>`);document.querySelector('#close-published-duty').onclick=()=>dialog.close();}
function mine(){const submitted=services.every(s=>statusFor(state.rows,state.me.id,state.date,s.id)!=='not_submitted'),unavailable=submitted&&services.every(s=>statusFor(state.rows,state.me.id,state.date,s.id)==='not_available');return `<div class="page-heading"><div><h1>My availability</h1><p>Choose the services you can be part of.</p></div>${dateControl()}</div>${demoNotice()}<div class="narrow"><form class="panel" id="availability-form"><div class="panel-heading"><div><h2>${displayDate()}</h2><p>Choose services. Your admin will assign your duty.</p></div><span class="draft-badge ${submitted?'published':''}">${unavailable?'Not available':submitted?'Submitted':'Not responded'}</span></div><div class="availability-options">${services.map(s=>{const status=statusFor(state.rows,state.me.id,state.date,s.id);return `<label class="service-choice"><input type="checkbox" name="services" value="${s.id}" ${status==='available'?'checked':''}><span><strong>${s.name}</strong><small>${status==='not_submitted'?'Not responded':status==='available'?'You are available':'You are not available'}</small></span></label>`;}).join('')}</div><div class="overall-availability"><label class="service-choice overall-unavailable"><input type="checkbox" id="overall-unavailable" ${unavailable?'checked':''}><span><strong>Not available</strong><small>I cannot attend any service at ${campusName()} on this date.</small></span></label></div><div class="panel-footer"><p class="small muted">Select your services or choose Not available, then submit.</p><button class="btn primary" ${!state.me.active?'disabled':''}>${submitted?'Update':'Submit'} Availability</button></div></form><p class="small muted" style="margin-top:18px;line-height:1.7">Being available makes you eligible for assignment. Your final duty will appear in the published service schedule.</p>${!state.me.active?'<div class="notice" style="margin-top:18px">Your account is inactive. Contact your team admin.</div>':''}</div>`;}
function profile(){const m=state.me;return `<div class="page-heading profile-page-heading"><div><h1>My profile</h1><p>A little about the person behind the service.</p></div></div>${demoNotice()}<form class="panel narrow profile-sheet" id="profile-form"><section class="profile-mobile-hero" aria-label="Your profile"><div class="profile-hero-content"><div class="profile-photo-wrap">${avatar(m)}<label for="profile-photo" class="profile-photo-trigger" aria-label="Change profile photo" tabindex="0">${icon('edit')}</label></div><div class="profile-identity"><h1>${esc(m.full_name||'New member')}</h1><p>${m.skills.map(skillName).join(' · ')||'Team member'}</p><span class="profile-status ${m.active?'':'inactive'}">${m.active?'Active member':'Inactive member'}</span></div></div><span class="profile-motto">For His glory</span></section><div class="profile-mobile-stats"><div>${icon('camera')}<span><strong>${m.skills.length}</strong><small>Roles</small></span></div><div>${icon('check')}<span><strong>${m.active?'Active':'Inactive'}</strong><small>Team member</small></span></div><div>${icon('users')}<span><strong>NLAG</strong><small>Video team</small></span></div></div><div class="panel-heading profile-desktop-heading">${person(m)}<span class="draft-badge">${m.active?'Active member':'Inactive member'}</span></div><section class="profile-personal"><div class="profile-section-heading"><span class="profile-section-icon">${icon('user')}</span><div><h2>Personal Information</h2><p>Your basic account details</p></div><button type="button" class="profile-edit" id="profile-edit">Edit</button></div><div class="form-grid"><label class="field">Full name<input class="input" name="full_name" value="${esc(m.full_name)}" required maxlength="100" autocomplete="name"></label><label class="field">Phone<input class="input" type="tel" name="phone" value="${esc(m.phone)}" maxlength="30" autocomplete="tel" required></label><label class="field full">Email<input class="input" value="${esc(m.email)}" disabled></label><label class="field full profile-upload">Profile photo<input id="profile-photo" class="input" type="file" name="photo" accept="image/jpeg,image/png,image/webp"><small class="muted">JPG, PNG, or WebP. Maximum 2 MB.</small></label></div></section><div class="profile-side"><section class="profile-skills"><div class="profile-section-heading"><span class="profile-section-icon">${icon('users')}</span><div><h2>Skills / Roles</h2><p>Roles assigned by the admin</p></div><span class="profile-admin-badge">Admin managed</span></div><div class="profile-role-list">${m.skills.map(s=>`<span class="tag profile-role role-${esc(s)}">${icon(s==='camera'?'camera':s==='producer'?'users':'grid')}${esc(skillName(s))}</span>`).join(' ')||'<span class="muted">No skills assigned yet</span>'}</div></section><div class="field full profile-user-id"><span class="muted small">User ID: ${esc(m.id)}</span></div><div class="panel-footer profile-actions"><span class="small muted">Your profile is linked to your account.</span><button class="btn primary">Save profile</button>${!state.demo?'<button type="button" class="btn profile-signout" data-action="signout">Sign out</button>':''}</div></div></form>`;}
function team(){const active=state.members.filter(m=>m.active),previous=state.members.filter(m=>!m.active);const card=(m,old)=>`<article class="panel member-card">${person(m)}<p class="small muted" style="overflow-wrap:anywhere">${esc(m.email)}</p><p class="small muted" style="margin-top:6px">${esc(m.phone||'Phone not added')}</p><div class="tags">${m.skills.map(s=>`<span class="tag">${skillName(s)}</span>`).join('')}<span class="tag">${m.active?'Active':'Previous member'}</span></div><div class="member-actions"><button class="btn" data-member="${m.id}">Manage skills & status</button><button class="btn ${old?'lime':'danger'}" data-member-${old?'restore':'remove'}="${m.id}">${old?'Restore member':'Move to previous members'}</button>${!m.is_admin&&m.id!==state.me.id?`<button class="btn danger" data-member-permanent="${m.id}">Remove permanently</button>`:''}</div></article>`;return `<div class="page-heading"><div><h1>Team members</h1><p>Skills, people, and a place to serve.</p></div><div class="team-page-actions"><span class="pill">${active.length} active members</span><button class="btn" data-report-back>Back to availability</button></div></div>${demoNotice()}<section class="team-section"><div class="section-label"><h2>Current team</h2><small>Active members can share availability and receive assignments.</small></div><div class="team-cards">${active.map(m=>card(m,false)).join('')||'<section class="panel empty-state">No active members yet.</section>'}</div></section>${previous.length?`<section class="team-section previous-members"><div class="section-label"><h2>Previous team members</h2><small>Deleted members are kept here so past schedules remain understandable.</small></div><div class="team-cards">${previous.map(m=>card(m,true)).join('')}</div></section>`:''}`;}
function login(){const register=state.view==='register';return `<main class="welcome-page ${register?'welcome-register':'welcome-login'}"><section class="welcome-story" aria-label="Welcome to NLAG Video Team Schedule"><div class="welcome-orbit" aria-hidden="true"></div><header class="welcome-header"><button class="welcome-brand" data-auth="login" aria-label="NLAG Video Team Schedule home"><img src="nlag-logo.png" alt=""><span>NLAG<span class="welcome-brand-sub">Video Team Schedule</span></span></button><span class="welcome-ministry">NEW LIFE ASSEMBLY OF GOD</span></header><div class="welcome-message"><span class="welcome-kicker"><span aria-hidden="true"></span> ONE TEAM. ONE PURPOSE.</span><h1>Behind every frame.<br><em>A greater purpose.</em></h1><p class="welcome-intro">Your creativity has a calling. Welcome to the team that brings faith into focus.</p><div class="scripture-card"><span class="scripture-label">A WORD FOR YOUR SERVICE</span><blockquote>“And whatsoever ye do, do it heartily, as to the Lord, and not unto men;”</blockquote><cite>Colossians 3:23 <span>· KJV</span></cite></div></div><footer class="welcome-story-footer"><span>Called to create.<br><strong>Connected to serve.</strong></span><span class="welcome-cross" aria-hidden="true"></span></footer></section><section class="welcome-access" aria-labelledby="welcome-form-title"><div class="welcome-form-wrap"><div class="welcome-form-top"><span class="welcome-step">${register?'YOUR NEXT CHAPTER':'YOUR TEAM IS HERE'}</span><span class="welcome-dot" aria-hidden="true"></span></div><h2 id="welcome-form-title">${register?'There’s a place <br>for you here.':'Welcome back, <br><span class="welcome-team">team.</span>'}</h2><p class="welcome-form-intro">${register?'Bring your gifts. Join the NLAG media family and be part of something meaningful.':'Ready to make a difference? Sign in to plan, connect, and serve together.'}</p>${state.authNotice?`<div class="auth-feedback success" role="status">${esc(state.authNotice)}</div>`:''}<form id="auth-form" class="welcome-form">${register?'<label class="field">Full name<input class="input" name="full_name" placeholder="Your full name" required autocomplete="name" maxlength="100"></label>':''}<label class="field">${register?'Email address':'Email or phone number'}<input class="input" name="email" type="${register?'email':'text'}" placeholder="${register?'you@example.com':'Email or phone (+91…)'}" required autocomplete="${register?'email':'username'}" autocapitalize="none" spellcheck="false"></label><label class="field">Password<input class="input" name="password" type="password" placeholder="${register?'Create a password':'Enter your password'}" required ${register?'minlength="12" aria-describedby="password-guide"':''} autocomplete="${register?'new-password':'current-password'}"></label>${register?'<p class="welcome-password-guide" id="password-guide">Use at least 12 characters.</p>':'<button type="button" class="welcome-forgot" data-auth="forgot_password">Forgot password?</button>'}<button class="btn primary welcome-submit">${register?'Join the team':'Sign in to Video Team Schedule'}<span aria-hidden="true">↗</span></button></form><div class="welcome-switch"><span>${register?'Already part of the team?':'New to the media family?'}</span><button type="button" data-auth="${register?'login':'register'}">${register?'Sign in':'Create your account'} <span aria-hidden="true">→</span></button></div><div class="welcome-blessing"><span aria-hidden="true">✦</span><p>May the work of your hands<br>bring light to someone’s life.</p></div></div><footer class="welcome-access-footer">NLAG Video Team Schedule <span>Made for ministry.</span></footer></section><div class="welcome-purpose" aria-hidden="true"><div><span>Capture</span><span>Create</span><span>Share</span><span>Serve</span></div><p>FOR HIS GLORY</p></div></main>`;}
function openAvailabilityPage(view){if(!state.me?.is_admin)return;if(!history.state?.availabilityReport)history.replaceState({...history.state,availabilityDashboard:true},'');state.view=view;history.pushState({availabilityReport:true,view},'',`#${{team:'team-members',responses:'responses-received',awaiting:'awaiting-response',unavailable:'not-available'}[view]}`);render();const heading=document.querySelector('h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}window.scrollTo(0,0);}
function availabilityReport(){if(!state.me?.is_admin)return '<div class="empty-state">Admin access required.</div>';const type=state.view,title={responses:'Responses received',awaiting:'Awaiting response',unavailable:'Not available'}[type];const members=state.members.filter(m=>m.active&&(type==='responses'?services.every(s=>statusFor(state.rows,m.id,state.date,s.id)!=='not_submitted'):type==='awaiting'?services.some(s=>statusFor(state.rows,m.id,state.date,s.id)==='not_submitted'):services.every(s=>statusFor(state.rows,m.id,state.date,s.id)==='not_available'))).sort((a,b)=>a.full_name.localeCompare(b.full_name));const card=m=>{const groups=[['available','Available for','check'],['not_available','Not available for','minus'],['not_submitted','Awaiting response for','clock']];return `<article class="panel response-member-card">${person(m)}<div class="response-service-groups">${groups.map(([status,label,i])=>{const items=services.filter(s=>statusFor(state.rows,m.id,state.date,s.id)===status);return items.length?`<section class="response-service-group ${status}"><h3>${icon(i)}${label}</h3><div class="response-service-tags">${items.map(s=>`<span>${esc(s.name)}</span>`).join('')}</div></section>`:'';}).join('')}</div></article>`;};return `<div class="report-back"><button class="btn" data-report-back>← Back to availability</button></div><div class="page-heading"><div><h1>${title}</h1><p>${campusName()} campus · ${displayDate()}</p></div>${dateControl()}</div>${demoNotice()}<div class="response-page-summary"><strong>${members.length}</strong><div><span>${members.length===1?'team member':'team members'}</span><p>${type==='responses'?'Submitted availability for this campus and date.':type==='awaiting'?'Availability has not been completed for this campus and date.':'Unavailable for every service at this campus on this date.'}</p></div></div><div class="response-member-grid">${members.map(card).join('')||`<section class="panel empty-state">${type==='responses'?'No responses received yet.':type==='awaiting'?'Everyone has responded.': 'No members marked unavailable for all services.'}</section>`}</div>`;}
window.addEventListener('popstate',event=>{if(!state.me?.is_admin)return;if(event.state?.availabilityReport){state.view=event.state.view;}else if(event.state?.availabilityDashboard){state.view='availability';}else return;render();window.scrollTo(0,0);});
async function switchService(serviceId){if(serviceSwitching||state.view!=='schedule'||serviceId===state.service||!services.some(s=>s.id===serviceId))return;const from=state.service,campus=state.campus,date=state.date;await safeNavigate(async()=>{if(serviceSwitching||state.view!=='schedule'||state.campus!==campus||state.date!==date||state.service!==from)return;const viewport=document.querySelector('#service-slide-viewport'),direction=services.findIndex(s=>s.id===serviceId)>services.findIndex(s=>s.id===from)?1:-1;state.service=serviceId;syncAssignments();if(!viewport||!canSlideService()){render();return;}serviceSwitching=true;try{const template=document.createElement('template');template.innerHTML=schedule();const incoming=template.content.querySelector('.service-slide-content');document.querySelectorAll('[data-service]').forEach(button=>{const active=button.dataset.service===serviceId;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});await slideService(viewport,incoming,direction);if(viewport.isConnected&&state.view==='schedule'&&state.service===serviceId&&state.campus===campus&&state.date===date)bind();}catch{if(state.view==='schedule'&&state.service===serviceId&&state.campus===campus&&state.date===date)render();}finally{serviceSwitching=false;}});}
function render(){cancelServiceSlide(document.querySelector('#service-slide-viewport'));if(state.loading){shell('<div class="empty-state"><h2>Loading your workspace…</h2></div>');return;}if(state.loadError){shell(`<div class="error-list" role="alert"><strong>Unable to load your workspace</strong><p>${esc(state.loadError)}</p><button class="btn" data-action="retry">Try again</button></div>`);return;}if(['login','register','forgot_password','reset_password'].includes(state.view)){app.innerHTML=['forgot_password','reset_password'].includes(state.view)?passwordRecoveryPage():login();bind();}else shell((({availability,schedule,mine,profile,team,responses:availabilityReport,awaiting:availabilityReport,unavailable:availabilityReport,login,register:login})[state.view]||login)());if(state.busy)app.querySelectorAll('button,input,select').forEach(x=>x.disabled=true);}
function bind(){document.querySelectorAll('[data-published-position]').forEach(button=>button.onclick=()=>publishedDutyDetails(button.dataset.publishedPosition));document.querySelectorAll('[data-availability-filter]').forEach(button=>button.onclick=()=>safeNavigate(()=>openAvailabilityPage({all:'team',responded:'responses',not_submitted:'awaiting',unavailable_all:'unavailable'}[button.dataset.availabilityFilter])));document.querySelectorAll('[data-report-back]').forEach(button=>button.onclick=()=>{if(history.state?.availabilityReport)history.back();else{state.view='availability';render();window.scrollTo(0,0);}});document.querySelectorAll('[data-campus]').forEach(b=>b.onclick=()=>safeNavigate(()=>{state.campus=b.dataset.campus;services=servicesFor(state.campus);state.service=services[0].id;state.filterService='all';syncAssignments();render();}));const editProfile=document.querySelector("#profile-edit");if(editProfile)editProfile.onclick=()=>{const input=document.querySelector('#profile-form [name="full_name"]');input?.focus();input?.select();};const photoTrigger=document.querySelector(".profile-photo-trigger");if(photoTrigger)photoTrigger.onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();document.querySelector("#profile-photo")?.click();}};const menuButton=document.querySelector("#open-menu");if(menuButton)menuButton.onclick=openMobileMenu;document.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>safeNavigate(()=>{state.view=state.me?.is_admin?'availability':'schedule';syncAssignments();render();}));const countInput=document.querySelector('#camera-count');if(countInput)countInput.onchange=()=>{const count=Number(countInput.value);countInput.value=String(state.cameraCount);const keep=positionsFor(count);const removed=Object.keys(state.assignments).filter(p=>!keep.includes(p));const apply=()=>{state.cameraCount=count;state.assignments=Object.fromEntries(Object.entries(state.assignments).filter(([p])=>keep.includes(p)));state.dirty=true;state.errors=[];render();};if(removed.length)confirmAction('Remove camera assignments?', 'Reducing the camera count will clear '+removed.map(positionName).join(', ')+'. Save or publish to store this change.',apply);else apply();};document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>safeNavigate(()=>{state.view=b.dataset.nav;syncAssignments();render();}));document.querySelectorAll('[data-service]').forEach(b=>b.onclick=()=>switchService(b.dataset.service));bindServiceSwipe(document.querySelector(state.me?.is_admin?'.schedule-swipe-surface':'#service-slide-viewport'),direction=>{const index=services.findIndex(s=>s.id===state.service),next=services[index+direction];if(next)switchService(next.id);},()=>state.view==='schedule'&&!state.busy&&!serviceSwitching&&!dialog.open);const dateInput=document.querySelector('#service-date');if(dateInput)dateInput.onchange=()=>{const value=dateInput.value;dateInput.value=state.date;if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return;safeNavigate(async()=>{state.date=value;state.loading=!state.demo;render();await refresh();syncAssignments();render();});};
 const search=document.querySelector('#search-members');if(search)search.oninput=()=>{state.search=search.value;document.querySelector('#availability-rows').innerHTML=availabilityRows();};for(const id of ['filterService','filterRole','filterStatus']){const el=document.getElementById(id);if(el)el.onchange=()=>{state[id]=el.value;document.querySelector('#availability-rows').innerHTML=availabilityRows();document.querySelector('#availability-overview-title').textContent=availabilityFilterTitle();};}
 document.querySelectorAll('[data-position]').forEach(b=>b.onclick=()=>pick(b.dataset.position));document.querySelectorAll('[data-member]').forEach(b=>b.onclick=()=>editMember(b.dataset.member));document.querySelectorAll('[data-member-remove]').forEach(b=>b.onclick=()=>setMemberActive(b.dataset.memberRemove,false));document.querySelectorAll('[data-member-permanent]').forEach(b=>b.onclick=()=>removePermanently(b.dataset.memberPermanent));document.querySelectorAll('[data-member-restore]').forEach(b=>b.onclick=()=>setMemberActive(b.dataset.memberRestore,true));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>{navigateAuth(b.dataset.auth);});
 const av=document.querySelector('#availability-form');if(av){const overall=av.querySelector('#overall-unavailable'),choices=[...av.querySelectorAll('[name="services"]')];av.onchange=e=>{state.mineDirty=true;if(e.target===overall&&overall.checked)choices.forEach(input=>input.checked=false);else if(e.target.name==='services'&&e.target.checked)overall.checked=false;};av.onsubmit=e=>{e.preventDefault();const selected=[...new FormData(av).getAll('services')];if(!state.me.full_name.trim()||!state.me.phone.trim()){toast('Complete your name and phone in My profile first.');return;}if(overall.checked)confirmAction('Not available for this day?',`All services at ${campusName()} on ${displayDate()} will be marked Not available.`,()=>submitAvailability([]));else if(!selected.length){toast('Select a service or choose Not available before submitting.');return;}else submitAvailability(selected);};}
 const pf=document.querySelector('#profile-form');if(pf){pf.oninput=e=>{state.profileDirty=true;};pf.onsubmit=e=>{e.preventDefault();saveProfile(new FormData(pf));};}const recover=document.querySelector('#forgot-password-form');if(recover)recover.onsubmit=e=>{e.preventDefault();requestPasswordReset(new FormData(recover));};const reset=document.querySelector('#reset-password-form');if(reset)reset.onsubmit=e=>{e.preventDefault();updateRecoveredPassword(new FormData(reset));};const af=document.querySelector('#auth-form');if(af)af.onsubmit=e=>{e.preventDefault();authenticate(new FormData(af));};}
async function busy(fn){if(state.busy)return;state.busy=true;const disabled=[...app.querySelectorAll('button,input,select'),...dialog.querySelectorAll('button,input')].map(x=>[x,x.disabled]);disabled.forEach(([x])=>x.disabled=true);try{await fn();}catch(e){toast(e.message||'Something went wrong. Please try again.');}finally{state.busy=false;disabled.forEach(([x,prior])=>x.disabled=prior);if(!document.contains(disabled[0]?.[0]))render();}}
async function refresh(){if(state.demo){state.loading=false;return;}if(!state.me){state.loading=false;return;}const seq=++refreshSequence;try{const data=await loadDay(state.date);if(seq!==refreshSequence)return;Object.assign(state,data);state.me=data.members.find(m=>m.id===state.me.id)||state.me;if(!state.me.is_admin){state.published=await rpc('published_schedule',{p_date:state.date});}state.loadError='';const photos=await Promise.all(state.members.filter(m=>m.avatar_url).map(async m=>[m.id,await photoUrl(m.avatar_url)]));for(const [id,url] of photos){const m=state.members.find(m=>m.id===id);if(m)m.photo=url;}}catch(e){state.loadError=e.message;}finally{state.loading=false;}}
async function action(name){if(name==='retry'){state.loadError='';state.loading=true;render();if(state.me)await refresh();else await start();render();return;}if(name==='signout'){safeNavigate(()=>busy(async()=>{const {error}=await db.auth.signOut();if(error)throw error;state.me=null;state.members=[];state.rows=[];state.schedules=[];state.published=[];state.view='login';render();}));return;}
 if(!state.me?.is_admin)return;if(name==='auto'){const errs=validate(state.assignments,state.members,state.rows,state.date,state.service,false,state.cameraCount);if(errs.length){state.errors=errs;render();return;}state.assignments=autoAssign(state.members,state.rows,state.date,state.service,state.assignments,state.cameraCount);state.dirty=true;state.errors=[];render();toast('Open positions filled where eligible members are available.');}
 if(name==='validate'){state.errors=validate(state.assignments,state.members,state.rows,state.date,state.service,true,state.cameraCount);render();if(!state.errors.length)toast(`Ready to publish. All ${state.cameraCount+2} duties are valid and unique.`);}
 if(name==='save')await saveSchedule(false);if(name==='publish'){state.errors=validate(state.assignments,state.members,state.rows,state.date,state.service,true,state.cameraCount);if(state.errors.length){render();return;}confirmAction(state.demo?'Preview publishing':'Publish this service?',state.demo?'This previews a published schedule using sample data. It is not saved to a database.':`Publish ${serviceName()} for ${displayDate()} to your team?`,()=>saveSchedule(true));}if(name==='whatsapp')whatsapp();if(name==='combined')await combinedSchedule();}
function pick(position){const people=candidates(state.members,state.rows,state.date,state.service,position);modal(`Assign ${positionName(position)}`,`<p class="small muted" style="margin-bottom:18px">Available for ${serviceName()} · ${displayDate()}</p>${people.map(m=>{const assigned=Object.entries(state.assignments).find(([p,id])=>id===m.id&&p!==position)?.[0];return `<button class="candidate" data-candidate="${m.id}" ${assigned?'disabled':''}>${person(m)}<small class="muted">${assigned?`Assigned to ${positionName(assigned)}`:state.assignments[position]===m.id?'Selected':'Select'}</small></button>`;}).join('')||'<div class="empty-state">No available members have this skill yet.</div>'}${state.assignments[position]?'<button class="btn" id="remove-assignment">Remove assignment</button>':''}${position.startsWith('cam_')?`<button type="button" class="candidate not-needed-choice" id="camera-not-needed">${icon('minus')}<span><strong>Standby</strong><small>Keep this camera on standby without assigning a member.</small></span><small>${state.assignments[position]==='not_needed'?'Selected':'Select'}</small></button>`:''}`);const notNeeded=document.querySelector('#camera-not-needed');if(notNeeded)notNeeded.onclick=()=>{state.assignments[position]='not_needed';state.dirty=true;state.errors=[];dialog.close();render();};dialog.querySelectorAll('[data-candidate]').forEach(b=>b.onclick=()=>{state.assignments[position]=b.dataset.candidate;state.dirty=true;state.errors=[];dialog.close();render();});const rm=document.querySelector('#remove-assignment');if(rm)rm.onclick=()=>{delete state.assignments[position];state.dirty=true;dialog.close();render();};}
async function saveSchedule(publish){await busy(async()=>{const errors=validate(state.assignments,state.members,state.rows,state.date,state.service,publish,state.cameraCount);if(errors.length){state.errors=errors;render();return;}const payload={camera_count:state.cameraCount,service_date:state.date,service_id:state.service,assignments:{...state.assignments},status:publish?'published':'draft',revision:(currentSchedule()?.revision||0)+1};if(state.demo){state.schedules=state.schedules.filter(s=>!(s.service_date===state.date&&s.service_id===state.service));state.schedules.push(payload);}else{await rpc('save_schedule',{p_date:state.date,p_service:state.service,p_assignments:state.assignments,p_publish:publish,p_revision:currentSchedule()?.revision||0,p_camera_count:state.cameraCount});await refresh();}state.dirty=false;state.errors=[];render();toast(state.demo?`Sample ${publish?'publication':'draft'} previewed for this visit only.`:publish?'Service schedule published.':'Draft saved.');});}
async function submitAvailability(selected){await busy(async()=>{if(state.demo){state.rows=state.rows.filter(r=>!(r.user_id===state.me.id&&r.service_date===state.date&&services.some(s=>s.id===r.service_id)));state.rows.push(...services.map(s=>({user_id:state.me.id,service_date:state.date,service_id:s.id,status:selected.includes(s.id)?'available':'not_available'})));for(const s of state.schedules.filter(s=>s.service_date===state.date&&services.some(svc=>svc.id===s.service_id)&&!selected.includes(s.service_id))){if(Object.values(s.assignments).includes(state.me.id)){s.assignments=Object.fromEntries(Object.entries(s.assignments).filter(([,id])=>id!==state.me.id));s.status='draft';s.revision++;}}}else{await rpc('submit_campus_availability',{p_date:state.date,p_services:selected,p_campus:state.campus});await refresh();}state.mineDirty=false;render();toast(state.demo?'Sample availability updated for this visit only.':'Availability submitted to your team admin.');});}
async function saveProfile(form){await busy(async()=>{const full_name=String(form.get('full_name')).trim(),phone=String(form.get('phone')).trim();if(!full_name||!phone)throw Error('Enter your name and phone number.');let avatar_url=state.me.avatar_url;const file=form.get('photo');if(file?.size){if(state.demo){if(file.size>2*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Choose a JPG, PNG, or WebP under 2 MB.');state.me.photo=URL.createObjectURL(file);}else avatar_url=await uploadPhoto(state.me.id,file);}if(state.demo)Object.assign(state.me,{full_name,phone});else{await rpc('save_profile',{p_name:full_name,p_phone:phone,p_avatar:avatar_url});await refresh();}state.profileDirty=false;render();toast(state.demo?'Sample profile updated for this visit only.':'Profile saved.');});}
function setMemberActive(id,targetActive){const m=state.members.find(m=>m.id===id);if(!m||(!targetActive&&m.id===state.me?.id)){toast('You cannot delete your own admin account.');return;}confirmAction(targetActive?'Restore team member?':'Delete team member?',targetActive?`${m.full_name} will return to the current team.`:`${m.full_name} will be moved to Previous team members. Past schedules are preserved.`,()=>busy(async()=>{const skills=m.skills?.length?m.skills:['camera'];if(state.demo){Object.assign(m,{active:targetActive});for(const s of state.schedules){for(const [p,uid] of Object.entries(s.assignments||{})){if(uid===id&&!targetActive){delete s.assignments[p];s.status='draft';s.revision=(s.revision||0)+1;}}}}else{await rpc('manage_member',{p_user:id,p_skills:skills,p_active:targetActive});await refresh();}dialog.close();render();toast(targetActive?'Team member restored.':'Team member moved to Previous team members.');}));}
function editMember(id){const m=state.members.find(m=>m.id===id);modal(`Manage ${m.full_name}`,`<form id="member-form"><div class="field"><label>Skills / roles</label><div class="checkboxes">${['camera','producer','ccu'].map(s=>`<label><input type="checkbox" name="skills" value="${s}" ${m.skills.includes(s)?'checked':''}>${skillName(s)}</label>`).join('')}</div></div><div class="checkboxes" style="margin:24px 0"><label><input type="checkbox" name="active" ${m.active?'checked':''} ${m.id===state.me.id?'disabled':''}>Active account</label></div><p class="small muted" style="line-height:1.6">Removing a skill or deactivating a member removes affected assignments and returns those schedules to draft.</p><div class="actions"><button class="btn primary">Save member</button></div></form>`);document.querySelector('#member-form').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target),skills=form.getAll('skills'),active=m.id===state.me.id?m.active:form.has('active');busy(async()=>{if(state.demo){Object.assign(m,{skills,active});for(const s of state.schedules){for(const [p,uid] of Object.entries(s.assignments)){if(uid===id&&(!active||!skills.includes(roleFor(p)))){delete s.assignments[p];s.status='draft';s.revision++;}}}}else{await rpc('manage_member',{p_user:id,p_skills:skills,p_active:active});await refresh();}dialog.close();render();toast(state.demo?'Sample member updated for this visit only.':'Member updated.');});};}
function whatsapp(){const s=currentSchedule();const positions=positionsFor(s?.camera_count??8);if(s?.status!=='published'||state.dirty){toast('Publish the schedule first.');return;}const text=`${state.demo?'SAMPLE SCHEDULE — NOT LIVE\n\n':''}*NLAG VIDEO TEAM SCHEDULE*\n${campusName()} Campus\n${displayDate()}\n*${serviceName()}*\n\n${positions.map(p=>`${positionName(p)}: ${s.assignments[p]==='not_needed'?'Standby':state.members.find(m=>m.id===s.assignments[p])?.full_name||'Unassigned'}`).join('\n')}\n\nThank you for serving!`;modal('WhatsApp schedule',`<p class="small muted" style="margin-bottom:15px">Review and copy this schedule to your team group.</p><textarea id="schedule-text" aria-label="WhatsApp schedule text" readonly>${esc(text)}</textarea><div class="actions"><button class="btn primary" id="copy-schedule">Copy schedule</button></div>`);document.querySelector('#copy-schedule').onclick=async()=>{try{await navigator.clipboard.writeText(text);toast('Schedule copied. Ready to paste into WhatsApp.');}catch{document.querySelector('#schedule-text').select();toast('Select and copy the schedule text.');}};}
function recoveryMarker(){try{const marker=JSON.parse(sessionStorage.getItem('nlag-password-recovery')||'null');return marker&&Date.now()-marker.startedAt<3600000?marker:null;}catch{return null;}}
function clearRecoveryMarker(){try{sessionStorage.removeItem('nlag-password-recovery');}catch{}state.recovery=false;state.recoveryUserId=null;}
function rememberRecovery(userId){state.recovery=true;state.recoveryUserId=userId;try{sessionStorage.setItem('nlag-password-recovery',JSON.stringify({userId,startedAt:Date.now()}));}catch{}}
function scrubAuthReturn(){const url=new URL(location.href);url.hash='';for(const key of ['error','error_code','error_description'])url.searchParams.delete(key);history.replaceState(history.state,'',url.pathname+url.search);}
async function navigateAuth(view){if(state.busy)return;if(state.recovery){if(configured){const {error}=await db.auth.signOut({scope:'local'});if(error){toast('Unable to leave password reset. Please try again.');return;}}clearRecoveryMarker();}state.authError='';state.authNotice='';state.view=view;render();document.querySelector('.welcome-form input')?.focus({preventScroll:true});}
function passwordRecoveryPage(){const reset=state.view==='reset_password',valid=reset&&state.recovery&&state.recoveryUserId;const title=reset?'Choose a new <br>password.':'Forgot your <br>password?';const intro=reset?'Create a secure password for your NLAG account.':'Enter your registered email. We’ll send you a secure password reset link.';const content=`<div class="welcome-form-top"><span class="welcome-step">${reset?'A FRESH START':'BACK TO YOUR TEAM'}</span><span class="welcome-dot" aria-hidden="true"></span></div><h2 id="welcome-form-title">${title}</h2><p class="welcome-form-intro">${intro}</p>${state.authError?`<div class="auth-feedback error" role="alert">${esc(state.authError)}</div>`:''}${reset&&!valid?'<div class="auth-feedback error" role="alert">Open a valid reset link from your email to choose a new password.</div><button class="btn primary welcome-submit" data-auth="forgot_password">Request a new link</button>':reset?`<form id="reset-password-form" class="welcome-form"><label class="field">New password<input class="input" type="password" name="new_password" minlength="12" required autocomplete="new-password" aria-describedby="reset-password-guide" placeholder="Create a new password"></label><label class="field">Confirm new password<input class="input" type="password" name="confirm_password" minlength="12" required autocomplete="new-password" placeholder="Enter it again"></label><p class="welcome-password-guide" id="reset-password-guide">Use at least 12 characters.</p><button class="btn primary welcome-submit">${state.busy?'Saving password…':'Save new password'}<span aria-hidden="true">↗</span></button></form>`:`${state.resetEmailSent?'<div class="auth-feedback success" role="status">If an account exists for this email, a reset link has been sent. Check your inbox and spam folder.</div>':''}<form id="forgot-password-form" class="welcome-form"><label class="field">Email address<input class="input" type="email" name="reset_email" required autocomplete="email" autocapitalize="none" spellcheck="false" value="${esc(state.resetEmail)}" placeholder="you@example.com"></label><button class="btn primary welcome-submit" ${Date.now()-state.resetLastRequestAt<60000?'disabled':''}>${state.busy?'Sending…':state.resetEmailSent?'Send another link':'Send reset link'}<span aria-hidden="true">↗</span></button>${Date.now()-state.resetLastRequestAt<60000?'<p class="welcome-password-guide">Please wait a minute before requesting another link.</p>':''}</form>`}<div class="welcome-switch"><button type="button" data-auth="login">← Back to sign in</button></div>`;const html=login(),begin=html.indexOf('<div class="welcome-form-top">'),end=html.indexOf('<div class="welcome-blessing">',begin);return (html.slice(0,begin)+content+html.slice(end)).replace('welcome-login"','welcome-login welcome-recovery"');}
function authRequestError(error,reset=false){if(error?.status===429||/rate.*limit|too many/i.test(error?.message||''))return reset?'Too many password attempts. Please wait and try again.':'Too many email requests. Please wait before requesting another reset link.';if(error?.code==='weak_password'||error?.code==='same_password')return error.message||'Choose a stronger password that is different from your current password.';if(error?.code==='session_not_found'||error?.status===401)return 'This reset link has expired. Request a new link.';return reset?'Unable to save your password. Please try again or request a new reset link.':'Unable to send the reset link. Check your connection and try again.';}
async function requestPasswordReset(form){if(state.busy)return;state.resetEmail=String(form.get('reset_email')||'').trim();state.resetEmailSent=false;state.authError='';if(Date.now()-state.resetLastRequestAt<60000)return;if(!configured){state.authError='Password reset is available on the connected website.';render();return;}state.busy=true;render();try{const {error}=await db.auth.resetPasswordForEmail(state.resetEmail,{redirectTo:'https://nlagmediahub.xyz/'});if(error)throw error;state.resetEmailSent=true;state.resetLastRequestAt=Date.now();clearTimeout(resetCooldownTimer);resetCooldownTimer=setTimeout(()=>{if(state.view==='forgot_password')render();},60100);}catch(error){state.authError=authRequestError(error);}finally{state.busy=false;render();}}
async function updateRecoveredPassword(form){if(state.busy)return;state.authError='';const password=String(form.get('new_password')||''),confirmation=String(form.get('confirm_password')||'');if(password.length<12){state.authError='Use at least 12 characters.';render();return;}if(password!==confirmation){state.authError='The passwords do not match. Please enter them again.';render();return;}if(!state.recovery||!state.recoveryUserId){state.authError='Open a valid password reset link first.';render();return;}state.busy=true;render();try{const verified=await db.auth.getUser();if(verified.error||verified.data.user?.id!==state.recoveryUserId)throw {code:'session_not_found'};const {error}=await db.auth.updateUser({password});if(error)throw error;clearRecoveryMarker();state.me=null;state.members=[];state.rows=[];state.schedules=[];state.published=[];state.view='login';state.authNotice='Password updated. Sign in with your new password.';const signedOut=await db.auth.signOut({scope:'global'});if(signedOut.error)state.authNotice='Password updated. Sign in again with your new password.';}catch(error){state.authError=authRequestError(error,true);}finally{state.busy=false;render();}}
async function showRecoverySession(session){if(!session){clearRecoveryMarker();state.view='forgot_password';state.authError='This reset link has expired or already been used. Request a new link.';}else{const verified=await db.auth.getUser();if(verified.error||verified.data.user?.id!==session.user.id){clearRecoveryMarker();state.view='forgot_password';state.authError='Unable to verify this reset link. Please request a new link.';}else{if(state.view==='reset_password'&&state.recoveryUserId===session.user.id){state.loading=false;return;}rememberRecovery(session.user.id);state.me=null;state.view='reset_password';}}state.loading=false;render();}
async function authenticate(form){await busy(async()=>{const args={email:String(form.get('email')),password:String(form.get('password'))};const register=state.view==='register';const result=register?await db.auth.signUp({...args,options:{data:{full_name:String(form.get('full_name'))},emailRedirectTo:'https://nlagmediahub.xyz/'}}):await signInWithIdentifier(args.email.trim(),args.password);if(result.error)throw result.error;if(register&&!result.data.session){toast('Check your email to confirm your account, then sign in.');state.view='login';render();return;}await setSession(result.data.session);});}
async function setSession(session){if(!session){state.loading=false;state.view='login';render();return;}state.me={id:session.user.id,full_name:'',skills:[],phone:'',email:session.user.email};await refresh();state.view=state.me.is_admin?'availability':state.me.full_name&&state.me.phone?'mine':'profile';syncAssignments();render();}
async function start(){try{if(!configured){render();return;}await connect();let starting=true;db.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'&&session&&!initialAuthLinkError){rememberRecovery(session.user.id);setTimeout(()=>showRecoverySession(session),0);}else if(event==='SIGNED_OUT'){clearRecoveryMarker();state.me=null;state.members=[];state.rows=[];state.schedules=[];state.view='login';render();}else if(event==='SIGNED_IN'&&!starting&&!state.recovery&&!initialAuthLinkError&&session?.user.id!==state.me?.id)setTimeout(()=>setSession(session),0);});const {data,error}=await db.auth.getSession();if(error)throw error;starting=false;if(initialAuthLinkError){clearRecoveryMarker();scrubAuthReturn();state.loading=false;state.view='forgot_password';state.authError='This reset link has expired or already been used. Request a new link.';render();return;}const marker=recoveryMarker(),matchingRecoverySession=initialRecoveryLink&&initialRecoveryFieldsComplete&&data.session?.access_token===authReturnHash.get('access_token');if(initialRecoveryLink&&!state.recovery&&!matchingRecoverySession){clearRecoveryMarker();scrubAuthReturn();state.loading=false;state.view='forgot_password';state.authError='This reset link is invalid, expired or already used. Request a new link.';render();return;}if(matchingRecoverySession||state.recovery||(marker&&marker.userId===data.session?.user.id)){scrubAuthReturn();await showRecoverySession(data.session);return;}clearRecoveryMarker();if(!(await checkSetup())){state.loading=false;state.loadError='Your team workspace is being prepared. Registration will open when the database setup is complete.';render();return;}await setSession(data.session);}catch(error){state.loading=false;state.loadError=error.message||'Unable to connect to your account.';render();}}
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});

setInterval(async()=>{if(!state.demo&&state.me&&!state.busy&&!serviceSwitching&&!state.dirty&&!state.mineDirty&&!state.profileDirty&&!dialog.open&&document.visibilityState==='visible'&&['availability','schedule','team','responses','awaiting','unavailable'].includes(state.view)){await refresh();if(!state.busy&&!serviceSwitching&&!state.dirty&&!state.mineDirty&&!state.profileDirty&&!dialog.open){syncAssignments();render();}}},15000);


window.addEventListener('beforeunload',e=>{if(state.dirty||state.mineDirty||state.profileDirty){e.preventDefault();e.returnValue='';}});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'read_service_availability',description:'Read the selected service date and availability counts visible to this admin. Does not submit availability or assign duties.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('No arguments accepted.');if(!state.me?.is_admin)throw Error('Admin access required.');return {sample:state.demo,date:state.date,services:services.map(s=>({name:s.name,available:state.members.filter(m=>m.active&&statusFor(state.rows,m.id,state.date,s.id)==='available').length}))};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}
render();start();
document.addEventListener('change',e=>{if(e.target?.id!=='profile-photo')return;const file=e.target.files?.[0],form=e.target.closest('#profile-form');if(!file||!form)return;if(file.size>2*1024*1024||!/^image\/(jpeg|png|webp)$/.test(file.type)){e.target.value='';toast('Choose a JPG, PNG, or WebP under 2 MB.');return;}const url=URL.createObjectURL(file),preview=form.querySelector('.profile-photo-wrap .avatar img'),avatarEl=form.querySelector('.profile-photo-wrap .avatar');if(preview)preview.src=url;else if(avatarEl)avatarEl.innerHTML='<img src="'+url+'" alt="" loading="lazy">';state.profileDirty=true;toast('Photo selected. Tap Save profile to keep it.');});
async function combinedSchedule(){
 if(state.busy)return;if(state.dirty){toast('Save or publish your schedule changes before combining schedules.');return;}
 if(!state.demo){await refresh();if(state.loadError){toast(state.loadError);return;}}
 const groups=campuses.map(c=>({campus:c,items:servicesFor(c.id).map(service=>({service,schedule:state.schedules.find(s=>s.service_date===state.date&&s.service_id===service.id&&s.status==='published')}))}));
 if(groups.some(g=>!g.items.some(i=>i.schedule))){toast('Publish at least one service in each campus before combining schedules.');return;}
 const lines=[state.demo?'SAMPLE — NOT LIVE':'*NLAG VIDEO TEAM SCHEDULE*',displayDate()];
 for(const group of groups){lines.push('',`*${group.campus.name.toUpperCase()} CAMPUS*`);for(const {service,schedule} of group.items){lines.push('',`*${service.name}*`);if(!schedule){lines.push('Not published yet');continue;}for(const p of positionsFor(schedule.camera_count??8))lines.push(`${positionName(p)}: ${schedule.assignments[p]==='not_needed'?'Standby':state.members.find(m=>m.id===schedule.assignments[p])?.full_name||'Unassigned'}`);}}
 lines.push('','Thank you for serving!');
 modal('Combined campus schedule',`<p class="small muted">Published services for both campuses. Unpublished services are clearly marked.</p><textarea id="combined-text" aria-label="Combined campus schedule" readonly>${esc(lines.join('\n'))}</textarea><div class="actions"><button class="btn primary" id="copy-combined">Copy both campuses</button></div>`);
 document.querySelector('#copy-combined').onclick=async()=>{try{await navigator.clipboard.writeText(lines.join('\n'));toast('Combined schedule copied.');}catch{document.querySelector('#combined-text').select();}};
}
function removePermanently(id){
 const member=state.members.find(m=>m.id===id);if(!state.me?.is_admin||!member||member.is_admin||id===state.me.id)return;
 modal('Remove member permanently',`<p><strong>${esc(member.full_name)}</strong> will lose their account, profile, photo, availability and assignments. Affected schedules will return to draft. This cannot be undone.</p><form id="permanent-delete-form"><label class="field" style="margin-top:18px">Type DELETE to confirm<input class="input" name="confirmation" required pattern="DELETE" autocomplete="off"></label><div class="actions"><button type="button" class="btn" id="cancel-permanent">Cancel</button><button class="btn danger">Remove permanently</button></div></form>`);
 document.querySelector('#cancel-permanent').onclick=()=>dialog.close();
 document.querySelector('#permanent-delete-form').onsubmit=e=>{e.preventDefault();if(new FormData(e.target).get('confirmation')!=='DELETE')return;busy(async()=>{
 if(state.demo){state.members=state.members.filter(m=>m.id!==id);state.rows=state.rows.filter(r=>r.user_id!==id);for(const s of state.schedules){if(Object.values(s.assignments).includes(id)){s.assignments=Object.fromEntries(Object.entries(s.assignments).filter(([,uid])=>uid!==id));s.status='draft';s.revision++;}}}
 else{const {data,error}=await db.functions.invoke('delete-team-member',{body:{user_id:id}});if(error||data?.error)throw Error(data?.error||error.message);await refresh();}
 dialog.close();render();toast('Member permanently removed.');
 });};
}
